CREATE OR REPLACE FUNCTION public.claim_first_admin() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Administrator access must be assigned by the project owner'; END $$;
REVOKE EXECUTE ON FUNCTION public.claim_first_admin() FROM public, anon, authenticated;
CREATE OR REPLACE FUNCTION public.guard_order_item_update() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF (to_jsonb(new) - 'status') IS DISTINCT FROM (to_jsonb(old) - 'status') THEN RAISE EXCEPTION 'Only status can be changed'; END IF; IF old.status IN ('delivered','cancelled') AND new.status <> old.status THEN RAISE EXCEPTION 'Final order status cannot be changed'; END IF; IF new.status <> old.status AND NOT ((old.status='pending' AND new.status IN ('confirmed','cancelled')) OR (old.status='confirmed' AND new.status IN ('shipped','cancelled')) OR (old.status='shipped' AND new.status='delivered')) THEN RAISE EXCEPTION 'Invalid order transition'; END IF; RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.guard_order_update() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF coalesce(current_setting('app.internal',true),'')='1' THEN RETURN new; END IF; IF (to_jsonb(new)-'status') IS DISTINCT FROM (to_jsonb(old)-'status') THEN RAISE EXCEPTION 'Only status can be changed'; END IF; IF new.status <> old.status AND NOT ((old.status='pending' AND new.status IN ('confirmed','cancelled')) OR (old.status='confirmed' AND new.status IN ('shipped','cancelled')) OR (old.status='shipped' AND new.status='delivered')) THEN RAISE EXCEPTION 'Invalid order transition'; END IF; RETURN new; END $$;
CREATE TRIGGER orders_guard BEFORE UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.guard_order_update();
CREATE OR REPLACE FUNCTION public.guard_order_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF new.phone IS NULL OR new.phone !~ '^01[3-9][0-9]{8}$' OR new.recipient IS NULL OR char_length(btrim(new.recipient)) NOT BETWEEN 2 AND 100 OR new.address_line IS NULL OR char_length(btrim(new.address_line)) NOT BETWEEN 5 AND 300 THEN RAISE EXCEPTION 'Invalid delivery details'; END IF; RETURN new; END $$;
CREATE TRIGGER orders_validate BEFORE INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION public.guard_order_insert();
CREATE OR REPLACE FUNCTION public.guard_demo_stock() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF coalesce(current_setting('app.internal',true),'')='1' AND EXISTS (SELECT 1 FROM public.seller_stores WHERE id=old.store_id AND is_demo) THEN RAISE EXCEPTION 'Demo products cannot create real orders'; END IF; RETURN new; END $$;
CREATE TRIGGER products_demo_guard BEFORE UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.guard_demo_stock();
CREATE OR REPLACE FUNCTION public.guard_product_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN new.rating:=0; new.sold_count:=0; END IF; RETURN new; END $$;
CREATE TRIGGER products_insert_guard BEFORE INSERT ON public.products FOR EACH ROW EXECUTE FUNCTION public.guard_product_insert();
CREATE OR REPLACE FUNCTION public.guard_application_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN new.status:='pending'; new.admin_note:=NULL; new.reviewed_at:=NULL; IF EXISTS (SELECT 1 FROM public.seller_applications WHERE user_id=new.user_id AND status='pending') THEN RAISE EXCEPTION 'An application is already pending'; END IF; IF EXISTS (SELECT 1 FROM public.seller_stores WHERE owner_id=new.user_id) THEN RAISE EXCEPTION 'A store already exists'; END IF; RETURN new; END $$;
CREATE TRIGGER applications_insert_guard BEFORE INSERT ON public.seller_applications FOR EACH ROW EXECUTE FUNCTION public.guard_application_insert();